let value = 0;
const display = document.getElementById("count");

function render() {
  display.textContent = value;
  display.style.color = value > 0 ? "green" : value < 0 ? "crimson" : "gray";
}

document.getElementById("inc").addEventListener("click", function () { value++; render(); });
document.getElementById("dec").addEventListener("click", function () { value--; render(); });
document.getElementById("reset").addEventListener("click", function () { value = 0; render(); });
render();

